import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/eshlk.html","title":"eshlk","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.83,"words":249},"filePathRelative":"eshlk.md"}`),a={name:`eshlk.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="eshlk" tabindex="-1"><a class="header-anchor" href="#eshlk"><span>eshlk</span></a></h1><p>embedなshell likeな言語を作りたい、という事で、まずは名前を決めてみた。eshlkという名前にする。 <a href="./自作アプリ.html">自作アプリ</a>（の予定）。 <a href="./TypeScript.html">TypeScript</a>で作る（予定）。</p><p><a href="./embed用のシェルのような何か.html">embed用のシェルのような何か</a>で考えたもの。</p><p><a href="./Nushell.html">Nushell</a>みたいなシンタックスの文字列を渡すとJavaScriptにトランスパイルするものを作りたい。 JavaScriptは<a href="./Rhino.html">Rhino</a>で動く範囲で。 RhinoやNodeからトランスパイルしてevalする感じで実行していく。</p><p>コマンドライン的に使えるように、statementが終わっていない状態もちゃんと扱えるものを作りたい。</p><p>AndroidとPCで同じスクリプトを使いたい。</p><p><a href="./slog.html">slog</a>みたいな事をしている時に簡単なシェルスクリプトを書いたりしたい。</p><h2 id="目標とするスクリプト" tabindex="-1"><a class="header-anchor" href="#目標とするスクリプト"><span>目標とするスクリプト</span></a></h2><p>以下を動かすのを目標とする</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">ui_cd</span>
<span class="line">ls *.md | each {|f| </span>
<span class="line">    let title = read_lines $f | first | replace &#39;# *&#39; &#39;&#39;</span>
<span class="line">    let date = $f.name | replace &#39;-.*&#39; &#39;&#39; |  replace &#39;_&#39; &#39;&#39;</span>
<span class="line">    {title: $title, date: $date, file: $f}</span>
<span class="line">   }  | ui_select | get file | ui_editor</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="作業ログ" tabindex="-1"><a class="header-anchor" href="#作業ログ"><span>作業ログ</span></a></h2><p>作業したメモを書く場所。</p><h3 id="_2026-10-01-木" tabindex="-1"><a class="header-anchor" href="#_2026-10-01-木"><span>2026-10-01 (木)</span></a></h3><p>lsのastがなんとなく出来たのだが、globの実装が面倒だなぁ、という事に気づく。 当初はトランスパイラを作りたいな、とぼんやり思っていたが、そろそろその辺をちゃんと考える必要がありそう。</p><p>トランスパイラであれbackendを環境ごとに実装する単なるインタプリタであれ、結局lsとかglobを実装していく事には違いは無いので、 まずはlsとかglobを実装していくにあたり何をライブラリとして共通に提供して何を環境ごとに用意するかを考えていく必要があるよな。</p><p>なるべくeshlkとしてはライブラリ的に使うような切り口を考えたい。</p><h3 id="_2026-09-28-月" tabindex="-1"><a class="header-anchor" href="#_2026-09-28-月"><span>2026-09-28 (月)</span></a></h3><p>Nushellの理解が深まったので実装を少し進めている。 LiteParseはそれっぽく動いた。</p><p>とりあえず、</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">ls *.md</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>のfull parseを動かそう。そのためにはglob patternとstringのone ofを対応する必要があるか。</p><h3 id="_2026-09-26-土" tabindex="-1"><a class="header-anchor" href="#_2026-09-26-土"><span>2026-09-26 (土)</span></a></h3><p>なんとなくトークナイザを書き始める。何を作ったらいいのか良く分からないので目標とするスクリプトを眺めてみよう。</p><p>まず最初のコマンドで後のパースが変わる、というのがeshlkの特徴なので、普通の言語処理系みたいにparseってやるとIRがばーんと帰って来るんじゃなくて、 expr単位とかそういう単位で細かくパースしていきたい。</p><p>とりあえず以下を動かそう。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">ls *.md</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>まず最初のトークンを見ていろいろ判断するのが良さそう 何がありえるかな？</p><ul><li>knownなコマンド</li><li>let</li></ul><p>あれ、この二つだけか。 いや、exprな事もたぶんあるよな。</p><p>ちょっと<a href="./Nushell.html">Nushell</a>のドキュメントでも読みなおすか。</p>`,30)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};